+++ b/src/index.js
 // QueenOS worker-starter: a dependency-free router. No build step: every
 // src/**/*.js file is uploaded as an ES module, so imports must be relative.
 import { features } from "./features/index.js";

 const json = (body, status = 200) =>
   new Response(JSON.stringify(body, null, 2) + "\n", {
     status,
     headers: { "content-type": "application/json; charset=utf-8" },
   });

+const featureList = (slugs) =>
+  slugs.length === 0
+    ? "<li><em>No features registered.</em></li>"
+    : slugs.map((slug) => `        <li><a href="/features/${slug}">/${slug}</a></li>`).join("\n");
+
+const html = (slugs) => `<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Worker Starter</title>
+  <style>
+    :root { color-scheme: light dark; }
+    body {
+      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
+      max-width: 42rem;
+      margin: 3rem auto;
+      padding: 0 1.25rem;
+      line-height: 1.6;
+      color: #222;
+      background: #fafafa;
+    }
+    h1 { font-weight: 700; font-size: 1.75rem; margin-bottom: 0.25rem; }
+    .status { color: #15803d; font-weight: 600; }
+    code, pre { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
+    ul { padding-left: 1.25rem; }
+    li { margin: 0.35rem 0; }
+    a { color: #2563eb; text-decoration: none; }
+    a:hover { text-decoration: underline; }
+    .card {
+      background: #fff;
+      border: 1px solid #e5e7eb;
+      border-radius: 0.75rem;
+      padding: 1.5rem;
+      margin-top: 1.25rem;
+      box-shadow: 0 1px 2px rgba(0,0,0,0.04);
+    }
+    @media (prefers-color-scheme: dark) {
+      body { color: #e5e7eb; background: #0f172a; }
+      .status { color: #4ade80; }
+      .card { background: #1e293b; border-color: #334155; }
+      a { color: #60a5fa; }
+    }
+  </style>
+</head>
+<body>
+  <h1>Worker Starter</h1>
+  <p class="status">● OK</p>
+  <p>Worker is running. Health-check endpoint: <a href="/health"><code>/health</code></a>.</p>
+  <div class="card">
+    <h2>Registered features</h2>
+    <ul>
+${featureList(slugs)}
+    </ul>
+  </div>
+</body>
+</html>
+`;
+
 export default {
   async fetch(request) {
     const url = new URL(request.url);
     try {
       // Feature guards run on every request (auth, flags, rate limits, ...).
       for (const feature of features) {
         if (typeof feature.guard === "function") await feature.guard(request);
       }

       if (url.pathname === "/" || url.pathname === "") {
+        return new Response(html(features.map((f) => f.slug)), {
+          headers: { "content-type": "text/html; charset=utf-8" },
+        });
-        return json({ ok: true, app: "worker-starter", features: features.map((f) => f.slug) });
       }
       if (url.pathname === "/health") return json({ ok: true });

       const match = /^\/features\/([a-z0-9-]+)\/?$/.exec(url.pathname);
       if (match) {
         const feature = features.find((f) => f.slug === match[1]);
         if (feature) return await feature.handle(request);
       }
       return json({ ok: false, error: "not found", path: url.pathname }, 404);
     } catch (err) {
       return json({ ok: false, error: String((err && err.message) || err) }, 500);
     }
   },
 };

